// Rule summaries shown on rule chips and cards, with links to the Rules Manual pages.
export const MANUAL = 'https://prancingponypub.ru/mesbg2024/rules_manual/';

const PG = {
  seq: ['turn_sequence/', 'Turn Sequence'], pri: ['priority_phase/', 'Priority Phase'], mov: ['move_phase/', 'Move Phase'],
  sho: ['shoot_phase/', 'Shoot Phase'], fig: ['fight_phase/', 'Fight Phase'], wea: ['weapons_and_wargear/', 'Weapons and Wargear'],
};

export const RULES = {
  profile: { t: 'Model profiles', s: 'The row of numbers that says what a model can do: Move, Fight, Shoot, Strength, Defence, Attacks, Wounds, Courage and Intelligence.', refs: [['the_rules/#characteristics', 'Characteristics']], x: 'Every model has a profile. MV, Move Value: inches it can move each turn. FV, Fight Value: skill in combat, wins tied Duel Rolls. SV, Shoot Value: the D6 roll needed to hit when shooting (lower is better). S, Strength and D, Defence: compared on the To Wound chart. A, Attacks: dice in a fight and Strikes when it wins. W, Wounds: how many it can lose before it is slain. C, Courage and I, Intelligence: 2D6 rolls needed for some tests (lower is better). Heroes also have Might, Will and Fate.' },
  priority: { t: 'Priority', refs: [PG.pri, PG.seq], x: 'At the start of each turn both players roll a D6. The higher roller chooses which side has Priority. The side with Priority activates all its models first in the Move and Shoot phases and decides the order of the fights. A tie in the first turn is re-rolled; in later turns the player who did not choose last turn makes the choice.' },
  move: { t: 'Moving', refs: [PG.mov], x: 'A model moves up to its Move value in inches (usually 6″). It does not have to move in a straight line: here you can move a model in several legs until its Move is used up. Once you start moving another model, the first one\'s move is over. Models can\'t move through other models or impassable rocks.' },
  terrain: { t: 'Difficult Terrain', s: 'Difficult Terrain, such as brush: every inch moved in it costs two inches of Move.', refs: [PG.mov], x: 'The brush is Difficult Terrain. While any part of the base is in it, every 1″ moved costs 2″ of Move.' },
  cz: { t: 'Control Zones', refs: [PG.mov], x: 'Every model has a 1″ Control Zone around its base. An enemy may only enter it by Charging that model. A model that starts its move inside an enemy Control Zone may stay, Charge, or move away; inside the zone it can never get closer to that enemy. Models Engaged in Combat lose their Control Zone.' },
  charge: { t: 'Charging', refs: [PG.mov], x: 'A Charge is a move that ends in base contact with an enemy. The charger must have Line of Sight to the target at the start of its move: it must see some part of it past rocks and other models. Both models are then Engaged in Combat: they can\'t move or shoot, and they fight in the Fight phase.' },
  shoot: { t: 'Moving and shooting', refs: [PG.sho, PG.wea], x: 'A model can shoot if it is not Engaged in Combat and moved no more than half its Move Value this turn (3″ for a Move of 6″). If it moved at all, its Shoot Value gets 1 worse (4+ becomes 5+), but a natural 6 still hits. Difficult Terrain counts double here too, so a model in the brush can move only 1.5″ and still shoot. A crossbow cannot shoot in a turn its model moved. Range is measured base to base, and the target must be in Line of Sight.' },
  shootFight: { t: 'Shooting into a fight', refs: [PG.sho], x: 'Good models can never shoot at a model Engaged in Combat. Evil models can: after hitting and any In The Way rolls, they roll another D6. On a 4+ the target is hit; on a 1–3 the shot hits the Evil model in that fight closest to the shooter.' },
  hit: { t: 'Roll To Hit', s: 'A D6 equal to or higher than the Shoot Value hits; a natural 6 always hits.', refs: [PG.sho], x: 'Roll a D6 for the shot. A result equal to or higher than the model\'s Shoot Value (SV) hits: SV 4+ hits on a 4, 5 or 6. A natural 6 always hits, whatever the modifiers.' },
  itw: { t: 'In The Way', s: 'Terrain or a model that hides part of the target is In The Way: the shot needs a 4+ for each, or it stops there.', refs: [PG.sho], x: 'Look from the shooter\'s head at the whole target: every piece of terrain or model that hides any part of it is In The Way, even if the line between the centres misses it. If rocks, buildings, high ground or other models hide the whole target, there is no Line of Sight and no shot. Height counts: a man can\'t hide a troll, a model on a hill sees over the men in front of it, a cliff or a fortress wall hides the models below it, and low cover only hides what stands close behind it. For each obstruction roll a D6, closest first. On a 4+ the shot carries on; on a 1–3 it hits the obstruction, and if that is a model, roll To Wound against it instead. Good models can\'t shoot if that would risk hitting a friend: a friendly model In The Way, or an enemy In The Way that is fighting a friend. A friend in base contact with the shooter (same or smaller base) is ignored, unless that friend is Engaged in Combat, and so is a wall that friend is touching. Terrain the shooter is touching is ignored too, as long as it can still see the target over or around it.' },
  cover: { t: 'Shooting from behind cover', s: 'A shooter touching low cover it can see over ignores that cover: no In The Way test for it.', refs: [PG.sho], x: 'A model in base contact with a low wall, brush or similar cover that it can see over ignores that cover when it shoots: no In The Way test for it. A model shooting over the shoulder of a friend in base contact (same base size or smaller, not fighting) also ignores a wall that friend touches. Enemy shots at the model still have to get past the cover, so each one needs an In The Way test (4+), and on a 1–3 the cover takes the shot. Cover halves the enemy\'s chance to hit you; it does not make you safe. Walls this low do not stop movement: models step over them, but can\'t stand on top.' },
  wound: { t: 'To Wound', refs: [PG.sho], x: 'Cross-reference the attack\'s Strength with the target\'s Defence on the To Wound chart. The number is the D6 roll needed. "6/4" means roll a 6, then a 4+ on a second dice. Shots use the weapon\'s Strength, not the shooter\'s.' },
  duel: { t: 'Duel Roll', refs: [PG.fig], x: 'Each side rolls one D6 per Attack of its models in the fight. The side with the single highest dice wins. Only the winner strikes. More models in a fight means more dice.' },
  multi: { t: 'Multiple Combats', refs: [PG.fig], x: 'A Combat can have several models on one side. That side rolls one D6 for every Attack of all its models together; only the single highest dice counts, and the highest Fight Value on each side breaks a tie. If they win, each of them Strikes; if they lose, each of them Backs Away.' },
  tie: { t: 'Tied Duel Roll', refs: [PG.fig], x: 'If the highest dice are tied, the side with the higher Fight Value (FV) wins. That is why skilled fighters win ties.' },
  rolloff: { t: 'Roll-off', refs: [PG.fig], x: 'If the Fight Values are also equal, the player with Priority rolls a D6: on a 1–3 the Evil side wins, on a 4–6 the Good side wins.' },
  backaway: { t: 'Backing Away', refs: [PG.fig], x: 'Losing models Back Away exactly 1″ in a straight line, away from the winner, before any Strikes. They may cross Control Zones but can\'t end in base contact with an enemy, and they can\'t cross walls or other Obstacles. The owning player picks the direction: the rules only say it need not be directly away, and the app allows up to 60° off straight back. Until mission 8 the app picks for you; from then on you do.' },
  trapped: { t: 'Trapped', refs: [PG.fig], x: 'A loser that can\'t Back Away, because models, rocks or the table edge block it, is Trapped. Every Strike against it makes two To Wound rolls. If it survives, the models are then separated slightly so they are no longer in base contact. A friend standing in the way can Make Way for it (see Make Way).' },
  makeway: { t: 'Make Way', s: 'One friend not in Combat may step aside up to 1″, so a losing model can Back Away instead of being Trapped.', refs: [PG.fig], x: 'When a friend blocks a losing model\'s way back, one friendly model that is not Engaged in Combat may Make Way: it moves up to 1″ to clear the path, so its ally Backs Away instead of being Trapped. Only one friend can Make Way, it cannot cross impassable terrain or Obstacles, and it is optional. It may also be used just to keep a formation together, for example a spear stepping back behind the fighter it supports. Until mission 8 the app does this for you whenever it saves a model from being Trapped; from then on you choose.' },
  spear: { t: 'Spears and Supporting', s: 'A spear not in Combat Supports a fighting friend it touches: one more dice in the Duel Roll, and one Strike if its side wins.', refs: [PG.wea, PG.fig], x: 'A model with a spear that is not Engaged in Combat can Support a friend in base contact that is fighting, if the friend\'s base is the same size or smaller. It adds one dice to that Combat\'s Duel Roll, with its own Fight Value, and if its side wins it makes one Strike at any enemy in that Combat. It is not part of the Combat: it cannot be struck and does not Back Away. A spear supports one Combat per Fight phase, and not in a turn it shot. When a spear touches friends in several Combats, the app sends it where its side needs it most.' },
  pike: { t: 'Pikes', refs: [PG.wea, PG.fig], x: 'A pike Supports exactly like a spear. In addition, a model with a pike can Support a friendly pike that is itself Supporting a fighting friend, so the fighter gets two Supports: three ranks deep, three dice for one model in the front. Only a pike Supports through a pike, not through a spear. The risk: only one friend can Make Way, so a fighter that loses with two pikes right behind it usually cannot Back Away and is Trapped. A pike needs both hands: a model that also carries a shield or a missile weapon gets −1 on its Duel Roll dice (the models here have no shield).' },
  banner: { t: 'Banners', refs: [PG.wea, PG.fig], x: 'A banner reaches 3″ from its bearer. If a friendly model in a Combat, fighting or Supporting, is within 3″ of a friendly banner and can see it, one model of that side may re-roll one of its dice in the Duel Roll: one re-roll per Combat, however many banners are near. The re-roll comes after modifiers and also gets them, and the new result stands. The side that is losing decides first; then the other side may answer with its own banner. You may not re-roll a dice you are winning with in order to lose. The banner bearer itself gets −1 on its own Duel Roll dice, so keep it out of the fighting. Here a side re-rolls only when it is losing.' },
  shielding: { t: 'Shielding', refs: [PG.wea, PG.fig], x: 'A model with a shield (a light shield too) may declare Shielding at the start of a Combat, before the Duel Roll. It then rolls twice as many dice as its Attacks, but if its side wins it makes no Strikes: the losers still Back Away, or are Trapped, and nobody is wounded. In a Combat with several of your models, all of them shield or none, so all must carry shields. A Shielding model cannot be Supported, so a spear or pike behind it adds nothing. Cavalry cannot shield. If both sides could, the side with Priority declares first. Shield when you only have to hold, are outnumbered or would be Trapped; fight when you need to wound the enemy.' },
  twohanded: { t: 'Two-handed weapons', refs: [PG.wea], x: 'A model fighting with a two-handed weapon gets −1 on each of its Duel Roll dice, but a natural 6 stays a 6. Its Strikes get +1 on the To Wound roll (on both rolls of a 6/4). It cannot use a shield in the same Combat, and a shield gives it no Defence bonus. A model that also has a hand weapon chooses before the Duel Roll; here the orcs always swing their two-handed weapons. So they win fewer fights, but every fight they win hurts more.' },
  barriers: { t: 'Barriers', s: 'A model touching a wall or hedge it can see over, at least half the attacker\'s height, defends it: enemies must Charge to cross there.', refs: [['fight_phase/#barriers-38', 'Fight Phase: Barriers']], x: 'A model in base contact with a wall or hedge at least half its height defends it: its Control Zone reaches over the Barrier instead of stopping at it (a Control Zone normally stops at any Obstacle or impassable terrain), and no enemy may cross the Barrier inside that zone without Charging it. Only one model may Charge a defender over a Barrier: it stops against the Barrier as close to the defender as possible and counts as in base contact. The Duel Roll is normal, but Strikes come before Backing Away, nobody is Trapped, and each of the attacker\'s Strikes must first pass an In The Way test (4+). A beaten defender that survives does not Back Away: the attacker does. A slain defender\'s place may be taken by the attacker, which crosses the Barrier at once. A Prone model never defends a Barrier.' },
  bothsides: { t: 'Attacked from both sides', s: 'A defender also Charged on its own side of the Barrier loses its protection: a normal Combat, with Backing Away and Trapped.', refs: [['fight_phase/#attacked-from-both-sides-40', 'Fight Phase: Attacked from Both Sides']], x: 'A defender that is also Charged by an enemy on its own side of the Barrier loses its protection: the Combat is fought as any other, with Backing Away before the Strikes, Trapped if it cannot Back Away, and no In The Way tests. If the defender is slain, the attacker across the Barrier may still cross it. The other way round, an attacker that is Charged on its own side by a friend of the defender fights a normal Combat too, but may not cross the Barrier even if it slays the defender.' },
  cavalry: { t: 'Cavalry', refs: [['cavalry/#characteristics-for-cavalry-models', 'Cavalry']], x: 'A Cavalry model is a rider and a mount, each with its own profile. It moves with the mount\'s Move Value (10″ for a horse) and fights with the better Fight Value, Strength and Attacks of the two. Difficult Terrain costs it four times the distance, and it cannot Climb. A model that wins a Duel Roll against it chooses whether each Strike goes at the rider or the mount (the horse has its own Defence and Wounds). If the rider is slain, a horse flees; a Warg stays on a Courage Test and fights on. If the mount is slain, the rider takes a Thrown Rider Test and fights on, on foot, where the model stood, still Engaged with the enemies it was fighting.' },
  cavalrycharge: { t: 'Cavalry Charge', s: 'A Cavalry model that Charged infantry gets +1 Attack, and if it wins, knocks the infantry it fought to the ground (Prone).', refs: [['cavalry/#cavalry-charge-55-56', 'Cavalry: Cavalry Charge']], x: 'A Cavalry model that Charged this turn gets two bonuses in the Fight phase, as long as it fights only infantry, is not Engaged with enemy cavalry, is not in Difficult Terrain and has not been thrown: Extra Attack (+1 Attack: one dice more in the Duel Roll and one Strike more) and Knock to the Ground (if it wins, every infantry model it fought is knocked Prone after Backing Away, except Monsters and models with Strength 6 or more). Strikes against a Prone model make two To Wound rolls each. The bonuses stay even if other infantry Charges it afterwards, but not across a Barrier, and a Cavalry model that is Charged by infantry gets nothing.' },
  thrownrider: { t: 'Thrown Rider', s: 'When a mount is slain, the rider rolls a D6: 1 knocked flying (a hit, then Prone), 2–5 on its feet but done this turn, 6 fights on.', refs: [['cavalry/#thrown-rider-table', 'Cavalry: Thrown Rider Table']], x: 'When a Cavalry model\'s mount is slain, the rider takes a Thrown Rider Test once the Strikes are over: roll a D6. 1, Knocked Flying: one Strength 3 hit; if the rider survives it lies Prone and can do nothing more this turn. 2 to 5, Rises From the Dust: on its feet, but it can do nothing more this turn. 6, Leaps into Action: it fights on as normal. Either way the rider is now an infantry model on a 25 mm base where the Cavalry model stood, Engaged with the same enemies. An Expert Rider re-rolls a 1. A 1 on a Jump or Leap Test from the saddle, or a fall, throws the rider in the same way as a 1 on this table.' },
  shootcav: { t: 'Shooting at cavalry', s: 'A hit on a Cavalry model strikes the rider on a 4+ and the mount on a 1 to 3; then roll To Wound against that part.', refs: [['cavalry/#shooting-at-cavalry-54', 'Cavalry: Shooting at Cavalry']], x: 'A shot at a Cavalry model is aimed at the rider. After the To Hit roll and any In The Way tests, roll one more D6: on a 4+ the shot hits the rider, on a 1 to 3 it hits the mount instead. Then roll To Wound against the Defence of the part that was hit. A mount slain by a shot throws its rider (Thrown Rider Test), a rider slain leaves its mount on its own. A mounted archer shoots like any model: not after moving more than half its Move (5″ on a horse), and 1 worse To Hit after any move; it sees from the rider\'s head.' },
  loosemount: { t: 'A mount on its own', refs: [['cavalry/#separated-mounts', 'Cavalry: Separated Mounts']], x: 'When the rider is slain or thrown, the mount takes a Courage Test at once (2D6, its own Courage value). If it passes, it stays as a model of its own and fights on with its own profile; if it fails, it flees and is removed. A horse (Attacks 0) always flees. A Warg (Courage 8+) stays about two times in five: Fight 3, Strength 4, Move 10″, and it counts as a Mount, not infantry, so a Cavalry Charge against it gets no bonus. A rider never remounts.' },
  courage: { t: 'Courage Test', refs: [['courage_and_intelligence/#courage-44', 'Courage and Intelligence']], x: 'Roll 2D6: a total equal to or higher than the model\'s Courage value passes (7+ passes on 7 or more: 58% of the time; 8+: 42%). The rule that called for the test says what a failure means: in a Broken army the model flees the battlefield and counts as a casualty; a mount without its rider runs; a model that fails a Terror test cannot Charge that enemy this turn. A test passed for one reason covers every further test for the same reason that turn.' },
  broken: { t: 'Broken army', refs: [['courage_and_intelligence/#broken-army-46', 'Courage: Broken Army']], x: 'An army\'s Break Point is half the models it started with. At the start of a turn, if an army has lost more models than its Break Point (slain, escaped or fled), it is Broken for the rest of the game. From then on every model of that army must take a Courage Test when it Activates, before doing anything else: if it fails, it flees and is removed as a casualty. Models Engaged in Combat cannot Activate, so they do not test; every other model Activates in its side’s Activation phase, even one that does not move, and tests then. A Hero that passes calls Stand Fast for the Warriors near it: that comes with the Heroes.' },
  might: { t: 'Might', refs: [['heroes/#modify-dice-rolls-58-59-60', 'Heroes: Might']], x: 'A Hero may spend a Might Point to raise one of its own dice by 1, never above 6 and never down. Might is always the last thing to touch a roll: after re-rolls and every modifier. It works on the Hero\'s Duel Roll dice, its To Hit and To Wound rolls (on a 6+/4+ roll the points spent on the first dice carry over to the second), In The Way tests, Jump, Leap, Climb and Thrown Rider Tests, Courage Tests and the Fate Roll; never on a friend\'s or an enemy\'s dice, and never on the roll-off of a tied Duel Roll. When two Heroes fight, the one that is losing bids first, then the other may answer, back and forth, until both pass or the dice reach 6. Might also pays for Heroic Actions: those come in later missions.' },
  will: { t: 'Will', refs: [['heroes/#pass-a-courage-test-70', 'Heroes: Will']], x: 'A Hero may spend Will Points to raise a Courage Test by 1 each, and may mix in Might Points. Will also casts and resists Magical Powers: that is the chapter on magic.' },
  fate: { t: 'Fate', refs: [['heroes/#fate-71-72-73', 'Heroes: Fate']], x: 'Whenever a Hero suffers a Wound it may spend a Fate Point and roll a D6: on a 4+ the Wound is prevented. The points are spent one at a time, each roll settled before the next; a Might Point may raise a Fate Roll (a 3 to a 4), and that must be decided before the next Fate Point. Fate prevents any Wound dealt to the Hero, but not a flight after a failed Courage Test.' },
  obstacles: { t: 'Obstacles and heights', refs: [['move_phase/#obstacles-11', 'Move Phase: Obstacles']], x: 'Walls, hedges and fences are Obstacles. A model steps over one no taller than half its own height (a man over a low wall), but cannot stop on top of it. Taller than half its height, up to its height: a Jump Test. Taller than the model: a Climb Test, if there are handholds. Raised ground works the same way: a step up to half the model\'s height is walked up, and a drop no deeper than its height is Descended for free. Backing Away and Make Way never cross an Obstacle or take a test. Here a man is about 1.2″ tall with its base.' },
  jump: { t: 'Jump Test', s: 'Crossing an Obstacle: a D6 at it. 1 stays put, 2–5 lands across and stops, 6 lands and may move on.', refs: [['move_phase/#jumping-12', 'Move Phase: Jumping']], x: 'The model moves into base contact with the Obstacle and rolls a D6. 1: it stumbles, stays where it is and its activation ends. 2–5: it lands on the other side, in base contact with the Obstacle, and its move ends; if it landed in an enemy\'s Control Zone it must Charge that enemy by the shortest way, if its Move reaches (the closest one, if several). 6: it lands and may carry on moving. The distance across counts towards its Move.' },
  leap: { t: 'Leap Test', refs: [['move_phase/#leaping-13-14', 'Move Phase: Leaping']], x: 'A gap no wider than twice the model\'s height can be Leapt, if the model has enough Move to reach the other side. At the edge it rolls a D6. 1: it falls to the bottom of the gap, halfway across, takes Falling Damage and is Prone; its activation ends. 2–5: it lands on the far side and its move ends (with the same forced Charge as a Jump). 6: it lands and may carry on.' },
  climb: { t: 'Climb Test', s: 'Going up anything taller than the model: a D6 at its foot. 1 falls, 2–5 climbs as far as its Move goes, 6 may move on; climbing costs double.', refs: [['move_phase/#climbing-14-15', 'Move Phase: Climbing']], x: 'Going up anything taller than the model takes a Climb Test at its foot. 1: it falls and is Prone at the bottom (with Falling Damage if it fell from higher than its own height). 2–5: it climbs until its Move runs out or it reaches the top, where its move ends (with the same forced Charge as a Jump). 6: the same, and it may carry on. Every inch climbed counts double, as Difficult Terrain. A model that runs out of Move partway hangs there and must test again next turn. Climbing down a drop deeper than the model is the same; a smaller drop is Descended freely.' },
  falling: { t: 'Falling', refs: [['move_phase/#falling-and-falling-damage-17', 'Move Phase: Falling']], x: 'A model that falls is Prone at the bottom and its activation ends. If it fell further than its own height it takes Falling Damage: one Strength 3 hit, plus another for every full inch beyond its height. A model that loses a fight at the edge of a drop, with nowhere else to Back Away, must Back Away over it: the winner\'s Strikes come first, then it falls.' },
  prone: { t: 'Prone models', refs: [['move_phase/#prone-models', 'Move Phase: Prone models']], x: 'A Prone model has no Control Zone and is half its height for Line of Sight. In its move it can Crawl up to 1″ and do nothing else, or Stand Up for half its Move and then move on normally, even Charge. It cannot Charge, Jump, Leap or Climb while Prone. In a fight it rolls as usual, but if it wins it makes no Strikes (it may Stand Up instead), and if it loses it is always Trapped.' },
  strikes: { t: 'Strikes', refs: [PG.fig], x: 'The winner makes one Strike per Attack: a To Wound roll of its Strength against the loser\'s Defence. Each success removes 1 Wound, and a model with no Wounds left is slain. A winner fighting several enemies chooses where each Strike goes, one Strike at a time if it likes. Once you have learned Pairing Off you choose; before that the app picks for you.' },
  pairoff: { t: 'Pairing Off', refs: [PG.fig], x: 'At the start of the Fight phase, models in base contact are split into Combats. A Combat can have several models on one side but never on both, a model can only be put in a Combat with an enemy it touches, and every Engaged model must end up in a Combat. Where there is a choice, the player with Priority decides.' },
  order: { t: 'Order of Combats', refs: [PG.fig], x: 'Combats are fought one at a time, in the order chosen by the player with Priority. Order matters when a model blocks an enemy\'s way back: fight that Combat first, while the blocker still stands, and the enemy is Trapped if it loses.' },
  throwing: { t: 'Throwing weapons', refs: [['weapons_and_wargear/#throwing-weapons', 'Weapons: Throwing weapons']], x: 'A throwing weapon shoots in the Shoot phase even after a full Move. Once per turn a model may instead throw it as it Charges: it stops 1″ from the target and throws, with no penalty for moving. If the target survives, the Charge goes on against it; if it falls, the model may move on and even Charge someone else.' },
  sling: { t: 'Sling', s: 'A sling (12″, Strength 1) shoots twice if the model did not move, once after up to half its Move.', refs: [['weapons_and_wargear/#sling', 'Weapons: Sling']], x: 'A sling (12″, Strength 1) shoots twice in the Shoot phase if the model did not move at all, once if it moved up to half its Move, and not at all after more.' },
  blowpipe: { t: 'Blowpipe', refs: [['weapons_and_wargear/#blowpipe', 'Weapons: Blowpipe']], x: 'A blowpipe (12″, Strength 2) shoots like a bow and has Poisoned Attacks: To Wound rolls of a natural 1 are re-rolled.' },
  intelligence: { t: 'Intelligence Test', refs: [['courage_and_intelligence/#intelligence-48', 'Courage and Intelligence: Intelligence']], x: 'Roll 2D6: a total equal to or higher than the model’s Intelligence passes. The rule that called for the test says what a failure means. A Hero may add 1 for each Might Point it spends (not Will). A test passed for one rule covers every further test for the same rule that turn.' },
  terror: { t: 'Terror', refs: [['special_rules/#terror', 'Special rules: Terror']], x: 'A model that wishes to Charge a model with Terror takes a Courage Test at the start of its Move. Passed: it Charges as normal. Failed: it cannot Move at all this turn, but may still shoot and fight. Terror (Orc) and the like only frighten models with that keyword. A test passed for Terror covers every other Terror test that model takes this turn.' },
  fearful: { t: 'Fearful', refs: [['special_rules/#fearful', 'Special rules: Fearful']], x: 'A Fearful model that wishes to Charge takes a Courage Test at the start of its Move; if it fails, it cannot Move that turn but may otherwise act. Charging a model with Terror, it takes two tests: one for each rule.' },
  fearless: { t: 'Fearless', refs: [['special_rules/#fearless', 'Special rules: Fearless']], x: 'A Fearless model passes every Courage Test it has to take, without rolling: in a Broken army, against Terror, everywhere.' },
  swornProtector: { t: 'Sworn Protector', refs: [['special_rules/#sworn-protector-x', 'Special rules: Sworn Protector (X)']], x: 'A model with Sworn Protector (X) passes every Courage Test without a roll while the model named in brackets is alive and on the battlefield.' },
  bodyguard: { t: 'Bodyguard', s: 'Bodyguards pick a Hero of their army at the start; while it lives, they pass every Courage Test without a roll.', refs: [['special_rules/#bodyguard', 'Special rules: Bodyguard']], x: 'At the start of the game every Bodyguard picks a Hero of its army with its Faction keyword: the General, or else the Hero of the highest Heroic Tier; models of the same type pick the same Hero. While that Hero is alive and on the battlefield, its Bodyguards pass every Courage Test without a roll.' },
  harbingerOfEvil: { t: 'Harbinger of Evil', refs: [['special_rules/#harbinger-of-evil-x', 'Special rules: Harbinger of Evil (X)']], x: 'Enemy models within the range in brackets take a −1 penalty on their Courage Tests. Several such models do not add up, and a model with the rule ignores the enemy’s.' },
  survivalInstinct: { t: 'Survival Instinct', refs: [['special_rules/#survival-instinct', 'Special rules: Survival Instinct']], x: 'Every time a model with Survival Instinct suffers a Wound it does not prevent and survives, it takes a Courage Test, even if it passed one this turn. Failed: it flees and is removed as a casualty.' },
  timid: { t: 'Timid', refs: [['special_rules/#timid', 'Special rules: Timid']], x: 'A Cavalry model whose Mount is Timid takes a Courage Test (with the rider’s Courage) to Charge, and no rule passes it automatically. Failed: it cannot Move this turn. It never gets the Cavalry Charge bonuses.' },
  shieldwall: { t: 'Shieldwall', refs: [['special_rules/#shieldwall', 'Special rules: Shieldwall']], x: 'A model with Shieldwall and a shield gets +1 Defence while in base contact with two or more friends that have Shieldwall and a shield too. In Combat it is worked out before Backing Away, so it lasts the whole Combat. Prone and Cavalry models neither get nor give it.' },
  burly: { t: 'Burly', refs: [['special_rules/#burly', 'Special rules: Burly']], x: 'A Burly model takes no −1 on the Duel Roll for using a two-handed weapon, and Moves its full Move Value while carrying a Heavy Object.' },
  unyieldingCombatStance: { t: 'Unyielding Combat Stance', refs: [['special_rules/#unyielding-combat-stance', 'Special rules: Unyielding Combat Stance']], x: 'When this model would be knocked Prone, roll a D6: on a 4+ it keeps its footing. A rider who passes is still separated from the mount but counts as rolling a 6 on the Thrown Rider Chart, even after a Knocked Flying result.' },
  mightyHero: { t: 'Mighty Hero', refs: [['special_rules/#mighty-hero', 'Special rules: Mighty Hero']], x: 'A Mighty Hero gains a free Might Point at the start of each turn, even if its store is full. If it is not spent by the end of the turn, it is lost.' },
  intoTheFray: { t: 'Into the Fray', s: 'Helm Hammerhand declares a Heroic Combat each Fight phase for free; once he has slain an enemy, he must Charge whenever he Moves and can.', refs: [['heroes/#heroic-combat-fight-phase-64', 'Heroes: Heroic Combat']], x: 'Helm Hammerhand\'s own rule (War of the Rohirrim, p. 38): he may declare a Heroic Combat in each Fight phase without spending Might; it is still his one Heroic Action of that phase. After he has slain an enemy model, for the rest of the battle he must Charge an enemy model whenever he Moves, if he can.' },
  generalHunter: { t: 'General Hunter', refs: [['special_rules/#general-hunter', 'Special rules: General Hunter']], x: 'If this model slays the enemy General in a Combat, it immediately regains one Might Point it spent earlier in the battle.' },
  masterOfBattle: { t: 'Master of Battle', s: 'When an enemy Hero within 6″ declares a Heroic Action, a D6 on the number in brackets lets this model declare the same one for free.', refs: [['special_rules/#master-of-battle-x', 'Special rules: Master of Battle (X+)']], x: 'When an enemy Hero declares a Heroic Action within 6″ of this model, roll a D6: on the number in brackets or more, this model declares a Heroic Action of the same type without spending Might, even with no Might left.' },
  horseLord: { t: 'Horse Lord', refs: [['special_rules/#horse-lord', 'Special rules: Horse Lord']], x: 'Whenever the Mount of this model suffers a Wound, roll a D6: on a natural 6 the Wound is ignored. The rider may also spend its own Fate to prevent Wounds to its Mount.' },
  expertRider: { t: 'Expert Rider', s: 'A rider that re-rolls Jump, Swim and Thrown Rider Tests, and keeps its shield\'s +1 Defence on horseback even with a bow.', refs: [['special_rules/#expert-rider', 'Special rules: Expert Rider']], x: 'A Cavalry model with Expert Rider may re-roll the dice on Jump, Swim and Thrown Rider Tests, and keeps the +1 Defence of a shield while mounted even when it carries a bow.' },
  woodlandCreature: { t: 'Woodland Creature', refs: [['special_rules/#woodland-creature', 'Special rules: Woodland Creature']], x: 'A Woodland Creature moves through woods that are Difficult Terrain (the green brush) as if they were open ground. On a Cavalry model the Mount needs the rule too.' },
  mountainDweller: { t: 'Mountain Dweller', refs: [['special_rules/#mountain-dweller', 'Special rules: Mountain Dweller']], x: 'A Mountain Dweller moves through rocky Difficult Terrain (the grey scree) as if it were open ground, and may re-roll Jump, Leap and Climb Tests. On a Cavalry model the Mount needs the rule for the terrain.' },
  caveDweller: { t: 'Cave Dweller', refs: [['special_rules/#cave-dweller', 'Special rules: Cave Dweller']], x: 'A Cave Dweller adds 1 to its Jump, Leap and Climb Tests, and sees as far as normal when fighting in the dark.' },
  swiftMovement: { t: 'Swift Movement', refs: [['special_rules/#swift-movement', 'Special rules: Swift Movement']], x: 'A model with Swift Movement is never slowed by Difficult Terrain (except water) and crosses Obstacles without a Jump or Climb Test, though height climbed still counts towards its Move.' },
  spectralWalk: { t: 'Spectral Walk', refs: [['special_rules/#spectral-walk', 'Special rules: Spectral Walk']], x: 'A model with Spectral Walk is never slowed by Difficult Terrain and always counts as rolling a 6 on Climb, Jump, Leap and Swim Tests.' },
  expertShot: { t: 'Expert Shot', refs: [['special_rules/#expert-shot', 'Special rules: Expert Shot']], x: 'An Expert Shot makes two Shooting Attacks in the Shoot phase instead of one, one at a time, at the same or different targets, both with the same Missile Weapon.' },
  fellSight: { t: 'Fell Sight', refs: [['special_rules/#fell-sight', 'Special rules: Fell Sight']], x: 'A model with Fell Sight may Charge an enemy it cannot see, and can Charge or shoot a model with Stalk Unseen with no penalty.' },
  largeTarget: { t: 'Large Target', refs: [['special_rules/#large-target', 'Special rules: Large Target']], x: 'When shooting at a Large Target, only Monsters, Siege Engines and War Beasts can be In The Way: smaller models of either side are ignored.' },
  throwStones: { t: 'Throw Stones', s: 'A model that did not Move may throw stones in the Shoot phase, with the range and Strength in its profile.', refs: [['special_rules/#throw-stones', 'Special rules: Throw Stones']], x: 'A model that did not Move in the Move phase may make a Shooting Attack with thrown stones in the Shoot phase, with the range and Strength given in its profile.' },
  glorySeekers: { t: 'Glory Seekers', refs: [['special_rules/', 'Army lists: Glory Seekers']], x: 'A model with Glory Seekers adds 1 To Wound when it Strikes an enemy Hero it is Engaged with.' },
  phalanx: { t: 'Phalanx', refs: [['special_rules/', 'Army lists: Phalanx']], x: 'A model with Phalanx uses a pike and a shield together without the −1 on the Duel Roll. (Making Way with two friends is not played yet.)' },
  armyRule: { t: 'Army special rules', refs: [['matched_play/', 'Matched play: army lists']], x: 'Each army list has its own special rules. The game plays most of those of the target armies: Kingdom of Rohan, Army of Edoras, Minas Tirith, Usurpers of Edoras, Muster of Isengard, Wolves of Isengard and Legions of Mordor. The army card marks each rule as played or card only.' },
  heroRule: { t: 'Rules of named Heroes', s: 'A named Hero\'s own special rules, printed on its profile in the army list; the profile card marks the ones the game plays.', refs: [['matched_play/', 'Matched play: army lists']], x: 'Many named Heroes have special rules of their own, printed on their profile in the army list: the Warrior Poet of Háma, the Defender of Edoras (Haleth), the Usurper King (Wulf) and others. Some help the Warriors near the Hero. The profile card marks the ones the game plays.' },
  hatred: { t: 'Hatred', refs: [['special_rules/#hatred-x', 'Special rules: Hatred (X)']], x: 'A model with Hatred (X) adds 1 to its To Wound rolls when it Strikes a model with that keyword: Hatred (Man) against Man models. Hatred with no keyword works against every enemy.' },
  backstabbers: { t: 'Backstabbers', refs: [['special_rules/#backstabbers', 'Special rules: Backstabbers']], x: 'A Backstabber adds 1 to its To Wound rolls when it Strikes a Trapped model.' },
  ancientEnemies: { t: 'Ancient Enemies', refs: [['special_rules/#ancient-enemies-x', 'Special rules: Ancient Enemies (X)']], x: 'When a model with Ancient Enemies (X) Strikes a model with that keyword, it re-rolls To Wound rolls of a natural 1.' },
  poisonedAttacks: { t: 'Poisoned Attacks', refs: [['special_rules/#poisoned-attacks', 'Special rules: Poisoned Attacks']], x: 'A model with Poisoned Attacks re-rolls To Wound rolls of a natural 1, with its Strikes and its Shooting Attacks. A poisoned weapon gives the re-roll only to rolls made with that weapon.' },
  baneOfKings: { t: 'Bane of Kings', refs: [['special_rules/#bane-of-kings', 'Special rules: Bane of Kings']], x: 'A model with Bane of Kings re-rolls every failed To Wound roll, with its Strikes and its Shooting Attacks.' },
  venom: { t: 'Venom', refs: [['special_rules/#venom', 'Special rules: Venom']], x: 'A model with Venom re-rolls every failed To Wound roll when it Strikes. At the end of the Combat, pick one enemy it wounded but did not slay and roll a D6: on a natural 6 that model suffers another Wound.' },
  mightyBlow: { t: 'Mighty Blow', refs: [['special_rules/#mighty-blow', 'Special rules: Mighty Blow']], x: 'Each Strike of a model with Mighty Blow that causes a Wound the target does not prevent (with Fate) causes 2 Wounds instead of 1.' },
  baneWeapons: { t: 'Bane Weapons', refs: [['special_rules/#bane-weapons', 'Special rules: Bane Weapons']], x: 'A Bane Weapon is named after a keyword (Orcbane: Orc). Each of its Strikes that causes a Wound the target does not prevent causes D3 Wounds instead of 1 against a model with that keyword.' },
  bladesOfTheDead: { t: 'Blades of the Dead', refs: [['special_rules/#blades-of-the-dead', 'Special rules: Blades of the Dead']], x: 'A model with Blades of the Dead does not use the target’s Defence To Wound: the target counts its Defence as 10 minus its Courage (Courage 8+: Defence 2).' },
  standFast: { t: 'Stand Fast', refs: [['courage_and_intelligence/#stand-fast-47', 'Courage: Stand Fast']], x: 'A Hero of a Broken army that passes its Courage Test calls Stand Fast at the end of its Activation. A friendly Warrior that Activates later in the turn within 6″ of that Hero, and can see it, passes its own Courage Test without rolling. Other Heroes still take their own tests. A Hero that is Engaged in Combat does not Activate, so it does not test and calls no Stand Fast (unless it declared a Heroic Resolve).' },
  sharpshooter: { t: 'Sharpshooter', s: 'Shooting at a Cavalry model, it aims at the rider or the mount, and a hit lands on that part with no test.', refs: [['special_rules/#sharpshooter', 'Special Rules: Sharpshooter']], x: 'A model with Sharpshooter that shoots at a Cavalry model may aim at the rider or at the mount, and if the shot hits it hits the part it aimed at: no test for rider or mount. Heroic Accuracy gives a Hero this rule until the end of the turn.' },
  heroic: { t: 'Heroic Actions', refs: [['heroes/#heroic-actions-61-62', 'Heroes: Heroic Actions']], x: 'At the start of the Move, Shoot and Fight phases (in the Fight phase after Pairing Off) there is a Declare Heroic Actions step. The player without Priority goes first: declare one Heroic Action with one Hero, or pass; then the player with Priority does the same, and so on until both pass one after the other. A player who passed may still declare when the turn comes back. Each Heroic Action costs 1 Might Point, the same points that raise dice, and a Hero declares at most one per phase. Heroic Move, Shoot and Combat change the order of their phase: when both sides have one, the player with Priority rolls a D6: on 1–3 the Evil side chooses which of its Heroes goes first, on 4+ the Good side; then the sides take turns. A Hero that can no longer do it when its turn comes (Charged before its Heroic Move, say) loses the action and the point.' },
  heroicMove: { t: 'Heroic Move', s: 'Heroic Action in the Move phase: the Hero Activates before every other model, and with the shout With Me nearby friends follow at once.', refs: [['heroes/#heroic-move-move-phase-63', 'Heroes: Heroic Move']], x: 'Declared in the Move phase. The Hero Activates before every other model, whoever has Priority, and cannot Activate again later. As it Activates it may shout With Me: friends within 6″ of it that have not Activated yet then Activate right after it, in any order, and each must finish within 6″ of the Hero, or give up its Activation. A Hero that is Charged before its Heroic Move comes loses it, and the Might Point.' },
  heroicMarch: { t: 'Heroic March', s: 'Heroic Action in the Move phase: +3″ Move (5″ mounted) but no Charge; with the shout At the Double, nearby friends march too.', refs: [['heroes/#heroic-march-move-phase-65', 'Heroes: Heroic March']], x: 'Declared in the Move phase. The Hero adds 3″ to its Move this phase (5″ on horseback) but may not Charge. As it Activates it may shout At the Double: friends within 6″ that have not Activated yet get the same +3″ and no Charge, and must finish within 6″ of the Hero, or not move at all. A marching Hero still Activates in the usual order.' },
  heroicChannelling: { t: 'Heroic Channelling', s: 'Heroic Action in the Move phase: the Hero\'s next Casting Test this turn counts as a 6.', refs: [['heroes/#heroic-channelling-move-phase', 'Heroes: Heroic Channelling']], x: 'Declared in the Move phase by a Hero with Magical Powers. Its next Casting Test this turn counts as a 6 without rolling; it still spends one Will Point to Cast. A Resist Test then needs a 6.' },
  monsters: { t: 'Monsters', refs: [['monsters/#monsters-in-combat-74', 'Monsters: in Combat'], ['monsters/#brutal-power-attacks', 'Monsters: Brutal Power Attacks']], x: 'A Monster that slays a model with a Strike makes one free Strike at each model that was Supporting it. A Monster that wins may, once per turn, use a Brutal Power Attack instead of its Strikes: Rend (To Wound rolls equal to its Attacks against the target\'s Strength instead of its Defence), Barge (every enemy in the Combat and its supporters Back Away 3″, Prone if they cannot; the Monster then moves D3+3″ and may Charge again) or Hurl (throw a weaker model D3 plus the Strength difference at another enemy: two Strength 6 hits on it, one on the target, both Prone). Not while Prone.' },
  monstrousCharge: { t: 'Monstrous Charge', refs: [['special_rules/#monstrous-charge', 'Special rules: Monstrous Charge']], x: 'After a Charge the model has +1 Attack in the Fight phase (not on top of a Cavalry Charge\'s Extra Attack). If it Charged and wins the Duel Roll, every enemy in the Combat with less Strength is knocked Prone (riders are Knocked Flying) before it Strikes.' },
  fly: { t: 'Fly', refs: [['special_rules/#fly', 'Special rules: Fly']], x: 'The model flies over models and terrain, ignoring enemy Control Zones on the way and the height of what it crosses. It cannot land on another model, in a wood or on terrain nobody could reach; if it lands in an enemy’s Control Zone it must Charge that enemy.' },
  water: { t: 'Water features', refs: [['advanced_rules/#water-features', 'Advanced rules: Water features']], x: 'Shallow Water is Difficult Terrain (not for Cavalry, Monsters or War Beasts); a model that starts its Activation Prone in it takes a Swim Test. A model entering Deep Water, or starting its Activation in it, takes a Swim Test: 1 it drowns, 2–5 it swims half its remaining Move, 6 all of it (+1 Cavalry, −1 heavy armour, −1 shield, −1 banner). No shooting from Deep Water.' },
  night: { t: 'Fighting at Night', s: 'At night models see only 12″: no shots, Magical Powers or special rules further than that, and shots wound more easily in the dark.', refs: [['advanced_rules/#fighting-at-night', 'Advanced rules: Fighting at Night']], x: 'Models see only 12″: no Shooting Attacks, Magical Powers or special rules at a target further away, unless the shooter is a Cave Dweller or the target is lit (Blinding Light). Shots at a model in the dark get +1 To Wound (not at a Cave Dweller or a lit model).' },
  sentries: { t: 'Sentries', s: 'Sentries Activate first after a D6 on the Sentry Chart; until the alarm is raised they cannot shoot, Cast or use rules on enemies.', refs: [['advanced_rules/#sentries', 'Advanced rules: Sentries']], x: 'Sentries Activate first, after a D6 on the Sentry Chart: 1 no move, 2–3 the other player moves it up to half its Move, 4–5 its own player half, 6 its own player normally. Until the alarm is raised they cannot shoot, Cast or use special rules on enemies. The alarm goes up in the End phase if a Sentry is within 3″ of an enemy it can see, or was hit by a shot and survived.' },
  // Narrative Scenarios of the Battle of Edoras booklet (docs/edoras/; the booklet is not online, so the links go to the
  // Rules Manual's general rules the scenario rules build on).
  objectives: { t: 'Objective Markers', s: 'A side controls a marker when it has more models within 3″ of it than the enemy; a flaming brand counts as 2.', refs: [['matched_play/#objective-markers', 'Matched Play: Objective Markers'], ['narrative_play/#objectives', 'Narrative Play: Objectives']], x: 'An Objective Marker is a 25 mm marker on Open Ground: models move over it freely but may not end a move, Back Away or Make Way on top of it. In The Gates Fall (Battle of Edoras, p. 9) a side controls a marker when it has more models within 3″ of it than the enemy; a tie controls nothing. A Hill Tribesman with a flaming brand counts as 2 models (its profile, p. 17). Models Engaged in Combat still count.' },
  storehouses: { t: 'Burning Storehouses', s: 'Evil sets a Storehouse alight on a 6 (+1 flaming brand) at the end of the Move Phase; Good puts it out on 5+. Either may not shoot or Support that turn.', refs: [['narrative_play/#narrative-play-notes', 'Narrative Play: scenario special rules']], x: 'Torch the City (Battle of Edoras, p. 11). Set Alight the City: at the end of the Move Phase each Evil model in base contact with a Storehouse that is not on fire, and not Engaged in Combat, may roll a D6; on a 6 the Storehouse is set on fire (+1 with a flaming brand, so 5+). Put the Fires Out: a Good model that ends its Activation in base contact with a burning Storehouse, not Engaged, may roll a D6; on 5+ the fire is out. A model that tries either may not make a Shooting Attack in the following Shoot Phase, or Support a Combat in the following Fight Phase.' },
  hordes: { t: 'Hordes of Tribesmen', s: 'A slain Hill Tribesman is kept aside; at the end of each Evil Activation Phase it comes back on 4+ from any board edge, as Reinforcements.', refs: [['move_phase/#reinforcements-20', 'Move Phase: Reinforcements']], x: 'Last Stand of the Princes (Battle of Edoras, p. 13). Whenever a Hill Tribesman is slain it is put to one side. At the end of each Evil Activation Phase roll a D6 for each model kept aside: on 4+ it enters from any point on any board edge via the rules for Reinforcements: after the side’s other models have Activated it moves on from that point with all the usual rules, but it may not Charge for any reason.' },
  escape: { t: 'The Young Prince', s: 'Háma may leave the battlefield by moving off any board edge: the game ends at once in a draw.', refs: [['narrative_play/#objectives', 'Narrative Play: Objectives']], x: 'Last Stand of the Princes (Battle of Edoras, p. 13): Háma may escape the battlefield by Moving off the board via any board edge during his Activation. If he does, the game immediately ends and is a draw. In the game: move Háma until his base touches a board edge.' },
  scenario: { t: 'Matched Play Scenarios', refs: [['../scenarios/rules_manual/', 'Scenarios: the six of the Rules Manual']], x: 'Domination: five Objective Markers, 1–3 VP each for more models within 3″. Hold Ground: the centre, 4–12 VP for more models within 6″; Warbands arrive by Maelstrom of Battle. Destroy the Supplies: three markers a side, destroyed by a model in base contact in the End phase that did nothing but Move. Reconnoitre: Warbands arrive from your edge; models that reach the enemy edge escape and score. Fog of War: secret picks of a Hero to keep, one to hunt and a terrain piece to hold. Models move over Objective Markers but never end a move on one.' },
  siegeWalls: { t: 'Sieges', refs: [['sieges/#attacking-gates-and-doors', 'Sieges: Attacking Gates and Doors'], ['sieges/#siege-ladders', 'Sieges: Siege Ladders'], ['sieges/#the-grand-siege', 'Sieges: The Grand Siege']], x: 'Fortress walls are too tall to Climb: go up by the stairs or a Siege Ladder. A ladder is carried as a Heavy Object (half Move, or full Move with two bearers) and goes up when it reaches the wall; models climb it paying its height and Charge a defender at its top, one at a time. Losing there, a model does not Back Away but falls on a 1–3; winning with its enemy slain, it steps onto the battlements. A defender at the battlements where a ladder stands, with nobody at its top, may push it down on 4+ (+1 for each friend beside it, −1 for each enemy on it). The gate (Defence 10, 3 Wounds) only takes damage from shots of Strength 5 or more; at the end of the Fight phase every attacker touching it that did not fight Strikes it with no Duel Roll, two To Wound rolls a Strike. The attacker wins with 12 models on or within the walls in an End phase; the defender when the attacker is down to a quarter.' },
  ring: { t: 'The One Ring', refs: [['weapons_and_wargear/#the-one-ring', 'Weapons and Wargear: The One Ring']], x: 'The Ringbearer may put on the Ring during its Activation (not while Engaged; a mount bolts and the rider is thrown) and is then Invisible. Starting an Activation wearing it: Sauron’s Will, a D6 (Might may raise it), on a 1–2 the other player Moves it this turn. Taking it off takes a Courage Test. In matched play a lone Ringbearer wearing it as the last of its army is lost (My Precious).' },
  invisible: { t: 'Invisible', refs: [['special_rules/#invisible', 'Special rules: Invisible']], x: 'An Invisible model cannot be targeted by shots, Magical Powers or special rules, nor seen. It has no Control Zone and ignores the enemy’s; models move through it and it through them, but none ends a Move on another. Charging it takes an Intelligence Test, −1 for each full inch. Its Heroic Actions help nobody else and it gives no Stand Fast; fighting alone, it halves its enemies’ Fight Value.' },
  warBeast: { t: 'War Beasts', refs: [['war_beasts/#trample-77', 'War Beasts: Trample'], ['war_beasts/#stampede', 'War Beasts: Stampede']], x: 'A War Beast Moves by Trampling: it turns to face any way and Moves its full Move Value in a straight line, ignoring Control Zones, Difficult Terrain and water. Every model it runs into suffers its Impact Hits: slain, it goes on; standing, it stops there, Charging it. Charged by models of no greater combined Strength, it Tramples them first. It is never knocked Prone, Hurled, Barged or Trapped, never Backs Away, and if it wins after Charging, the beaten with no more Strength than it go Prone. It and its Commander are two models for the Break Point. Each Wound: a Courage Test on the Commander’s Courage, or it Stampedes in its next Activation, the other player turning it.' },
  chariot: { t: 'Chariots', s: 'A Chariot moves in straight lines, ignoring Control Zones, and every model it runs into suffers its Impact Hits.', refs: [['chariots/#chariot-charge', 'Chariots: Chariot Charge'], ['chariots/#immovable-object', 'Chariots: Immovable Object']], x: 'A Chariot Moves by Chariot Charge: it pivots up to 45° (again after each full 4″) and Moves up to its Move Value in a straight line, ignoring Control Zones; Difficult Terrain halves it, and a 1 on a D6 there costs it a Wound. Every model it runs into suffers its Impact Hits (a Cavalry model on rider and mount): if slain the Chariot goes on, if not it stops there, Charging it, with +1 Attack, and if it wins the beaten Infantry and Cavalry are knocked Prone. It is never knocked Prone, Hurled, Barged or Trapped, and never Backs Away: the winners touching it Back Away instead. A Hero riding one lends it its Fight Value, Strength, Courage and Intelligence where better and adds its Attacks; when the Chariot is destroyed the Hero is Knocked Flying.' },
  siege: { t: 'Siege Engines', refs: [['siege_engines/#siege-engines-and-shooting', 'Siege Engines: Shooting'], ['siege_engines/#attacking-a-siege-engine', 'Siege Engines: Attacking a Siege Engine']], x: 'A Siege Engine never Activates, has no Control Zone and is never Engaged. It fires in the Shoot phase when its crew stand in base contact and are not Engaged (2 for a Large engine, 1 for a Small one), with the worst Shoot Value among them (any other friend helps as untrained crew on 6+), at a target in range and in the 45° Arc of Sight it faces; turning it takes 3 (Large) or 2 (Small) models and costs −1 To Hit. A Battlefield Target that is hit scatters (D6: 1 wide, 2–5 the other player picks one of their models within 6″, 6 dead on), is knocked Prone, and if wounded is slain (Fate may save it). An enemy in base contact that only Moved that turn disables it in the End phase.' },
  magic: { t: 'Magical Powers', refs: [['magic/#using-magical-powers', 'Magic: Using Magical Powers'], ['magic/#magical-powers-list', 'Magic: the powers']], x: 'A model with Magical Powers may Cast one as it Activates in the Move phase (before, during or after its Move), if it has Will left and is not Prone. It names the power and the target (in range and in sight) and spends Will Points: one D6 each. If any dice reaches the Casting Value, the power is Cast; a Hero may raise the best dice with Might. An enemy target may then spend Will to Resist: one D6 each, and a dice equal to or above the best Casting dice resists it (a Hero gets back the Will of every natural 6). Instant powers happen at once, Temporary ones last until the End phase, Exhaustion ones until the caster runs out of Will; all end if the caster falls.' },
  resist: { t: 'Resisting Magical Powers', s: 'A model targeted by an enemy power may spend Will on a Resist Test: a dice equal to or above the best Casting dice stops it.', refs: [['magic/#resisting-a-magical-power-81', 'Magic: Resisting a Magical Power'], ['magic/#magical-power-durations', 'Magic: durations']], x: 'After the Casting Test and before the power takes effect, a model it targets may spend Will Points on a Resist Test, one D6 each, chosen before rolling. If any dice equals or beats the highest Casting dice, the power is resisted and has no effect. A Hero may raise a dice with Might, and regains the Will Point of every natural 6 it rolls (not on a free dice). A power with no enemy target (one on the caster or its friends) cannot be Resisted; for a power on several enemies, one of them Resists for all. A model hit only indirectly cannot Resist. Exhaustion powers last until the caster has no Will left; every power ends when its caster is slain.' },
  sorcerousBlast: { t: 'Sorcerous Blast', s: 'Instant, one enemy: a Strength 5 hit, then Prone; everyone else in its fight with Strength 5 or less is knocked Prone too.', refs: [['magic/#sorcerous-blast', 'Magic: Sorcerous Blast']], x: 'Duration Instant. The target enemy suffers one Strength 5 hit. If it survives, it is knocked Prone (a Cavalry model is Knocked Flying). If it was Engaged in a Combat, every other model in that Combat with Strength 5 or less is knocked Prone too, friends of the caster as well.' },
  transfix: { t: 'Transfix', s: 'Temporary, one enemy: until the End phase it cannot Activate, shoot or declare Heroic Actions, and makes no Strikes if it wins a fight.', refs: [['magic/#transfix', 'Magic: Transfix']], x: 'Duration Temporary. Until the End phase the target cannot Activate, declare Heroic Actions, use Active abilities or make Shooting Attacks. If it wins a Duel Roll, it may not make Strikes.' },
  spearMastery: { t: 'Spear Mastery', s: 'Throwing spears also fight as a spear (Support), unless thrown in this turn\'s Move or Shoot phase.', refs: [['weapons_and_wargear/#throwing-weapons', 'Weapons: Throwing weapons'], ['weapons_and_wargear/#spear-78', 'Weapons: Spear']], x: 'An army rule of Rohan (the Warriors of Rohan profile): the model may use its throwing spears as a normal spear during the Fight phase, so long as it has not made a Shooting Attack with them in the preceding Move phase (a throw as it Charged) or Shoot phase. As a spear it Supports a fighting friend in base contact.' },
  staffOfPower: { t: 'Staff of Power', s: 'A free Will Point at the start of each turn, lost if it is not spent by the end of that turn.', refs: [['weapons_and_wargear/#staff-of-power', 'Wargear: Staff of Power']], x: 'A Staff of Power is a hand-and-a-half weapon. Its wielder gains a free Will Point at the start of each turn; if it is not spent by the end of the turn, it is lost. The free point is spent first, on a Casting or a Resist Test alike.' },
  yourStaffIsBroken: { t: 'Your Staff is Broken', s: 'Instant, one enemy with a Staff of Power: the staff is destroyed.', refs: [['magic/#your-staff-is-broken', 'Magic: Your Staff is Broken']], x: 'Duration Instant. It targets one enemy model with a Staff of Power within range. The target\'s Staff of Power is destroyed and removed from its wargear, so it gains no more free Will Points.' },
  fury: { t: 'Fury', s: 'Exhaustion, on the caster: friends with the keywords in brackets within 6″ pass every Courage Test.', refs: [['magic/#fury-x', 'Magic: Fury (X)']], x: 'Duration Exhaustion: it lasts until the caster has no Will left, or falls. It targets the caster, so it cannot be Resisted. Friendly models within 6″ of the caster with the keywords in brackets (for the Uruk-hai Shaman: Isengard and Uruk-hai) automatically pass any Courage Test, so they do not flee from a Broken army.' },
  bladewrath: { t: 'Bladewrath', s: 'Temporary, one friend: in this turn\'s Fight phase its Strikes are made at Strength 6.', refs: [['magic/#bladewrath', 'Magic: Bladewrath']], x: 'Duration Temporary. It targets one friendly model in range, so it cannot be Resisted. In the ensuing Fight phase all its Strikes are resolved at Strength 6, whatever other modifiers apply.' },
  willOfEvil: { t: 'Will of Evil', refs: [['special_rules/#will-of-evil', 'Special rules: Will of Evil']], x: 'In the End phase the model gives up a Will Point if it fought in a Combat that turn; at 0 Will it is banished and removed as a casualty. It cannot spend its last Will Point to Cast a Magical Power.' },
  resistantToMagic: { t: 'Resistant to Magic', refs: [['special_rules/#resistant-to-magic', 'Special rules: Resistant to Magic']], x: 'Every time the model is the target of a Magical Power it rolls one free extra dice on its Resist Test, even with no Will left.' },
  heroicResolve: { t: 'Heroic Resolve', s: 'Heroic Action in the Move phase: the Hero passes its Broken army Courage Tests this turn and calls Stand Fast; friends nearby resist magic better.', refs: [['heroes/#heroic-resolve-move-phase-66', 'Heroes: Heroic Resolve']], x: 'Declared in the Move phase. The Hero passes every Courage Test it takes this turn for a Broken army without rolling, so it calls Stand Fast for the Warriors around it; even if it was Charged before it could Activate, it still Activates to call Stand Fast. It also gives friends within 6″ (and the Hero) a free dice on every Resist Test this turn, even with no Will left.' },
  heroicShoot: { t: 'Heroic Shoot', s: 'Heroic Action in the Shoot phase: the Hero shoots before every other model, and with the shout Loose nearby friends shoot with it.', refs: [['heroes/#heroic-shoot-shoot-phase', 'Heroes: Heroic Shoot']], x: 'Declared in the Shoot phase by a Hero that is not Engaged. The Hero shoots before every other model. It may shout Loose: friends within 6″ may shoot at the same time, at any targets; a friend that does not shoot then cannot shoot later in the phase.' },
  heroicAccuracy: { t: 'Heroic Accuracy', s: 'Heroic Action in the Shoot phase: the Hero gets Sharpshooter and re-rolls failed In The Way Tests; with Take Aim, nearby friends re-roll them too.', refs: [['heroes/#heroic-accuracy-shoot-phase-67', 'Heroes: Heroic Accuracy']], x: 'Declared in the Shoot phase by a Hero that is not Engaged. Until the end of the turn the Hero has Sharpshooter and re-rolls every failed In The Way Test when it shoots, including the tests for a shot into a fight and for the rider or mount of a Cavalry model. It may shout Take Aim: friends within 6″ re-roll their failed In The Way Tests too. The re-roll comes before Might.' },
  heroicCombat: { t: 'Heroic Combat', s: 'Heroic Action in the Fight phase: the Hero\'s Combat is fought first, and if every enemy in it falls, its side may move and Charge again.', refs: [['heroes/#heroic-combat-fight-phase-64', 'Heroes: Heroic Combat']], x: 'Declared in the Fight phase, after Pairing Off. The Hero\'s Combat is fought before every other. If its side wins and every enemy in that Combat is slain, the Hero and the friends that fought beside it may Move again at once, as in the Move phase, but only to Move or Charge; then the player with Priority Pairs Off again, and a new Combat is fought in the usual order. A model gets that extra move from one Heroic Combat per turn.' },
  heroicStrike: { t: 'Heroic Strike', s: 'Heroic Action in the Fight phase: the Hero adds a D3 to its Fight Value for the rest of the phase.', refs: [['heroes/#heroic-strike-fight-phase', 'Heroes: Heroic Strike']], x: 'Declared in the Fight phase. At the start of the first Combat the Hero fights in this phase it rolls a D3 and adds it to its Fight Value for the rest of the phase (to at most 10), after every other effect. A higher Fight Value wins tied Duel Rolls.' },
  heroicStrength: { t: 'Heroic Strength', s: 'Heroic Action in the Fight phase: the Hero doubles its Strength for its Strikes this turn.', refs: [['heroes/#heroic-strength-fight-phase', 'Heroes: Heroic Strength']], x: 'Declared in the Fight phase. Until the end of the turn the Hero doubles its Strength (to at most 10) when it makes Strikes: Strength 4 becomes 8 on the To Wound chart. The Duel Roll is not affected.' },
  heroicDefence: { t: 'Heroic Defence', s: 'Heroic Action in the Fight phase: for the rest of the phase the Hero is wounded only on a natural 6.', refs: [['heroes/#heroic-defence-fight-phase', 'Heroes: Heroic Defence']], x: 'Declared in the Fight phase. For the rest of the phase the Hero only suffers a Wound on a natural 6 (both natural 6s where 6+/4+ and the like are needed), whatever the Strength, modifiers, special rules or Might of its enemies. Its mount, if it rides one, is not protected.' },
  heroicChallenge: { t: 'Heroic Challenge', s: 'Heroic Action in the Fight phase: the Hero names an enemy Hero within 6″; against it, +1 Attack and +1 To Wound (the target too, if it accepts).', refs: [['heroes/#heroic-challenge-fight-phase-68-69', 'Heroes: Heroic Challenge']], x: 'Declared in the Fight phase against an enemy Hero within 6″ with the same Heroic Tier or higher (Legend, Valour, Fortitude, Minor, Independent). While Engaged in Combat with its target the Hero has +1 Attack (a dice in the Duel Roll and a Strike) and +1 To Wound against it; slaying the target gives back 1 Might Point. The target accepts or declines: if it accepts it gets the same bonuses against the challenger, and both must Charge each other when they can; if it declines it gets nothing and may never challenge that Hero itself. A challenge stands until one of the two is slain.' },
};

// Short texts and aliases of the glossary, for rule terms in the orders, the log and the cards (a term shows its short
// text; a click opens the full entry). An entry may set s (its own one or two lines) and aka (other words for it, such
// as 'Charge' for Charging); otherwise the short text is the first sentence of x, and the aliases come from the title
// (with its singular or plural). node tools/glossary-check.mjs checks lengths and clashes.
const firstSentence = x => { const m = /^(.+?[.!?])(?=\s+[A-Z(]|$)/.exec(x || ''); return m ? m[1] : x || ''; };
export const ruleShort = k => (RULES[k] ? RULES[k].s || firstSentence(RULES[k].x) : '');
export function ruleAliases(k) {
  const r = RULES[k]; if (!r) return [];
  const t = r.t, out = new Set([t, ...(r.aka || [])]);
  if (/[^s]s$/.test(t)) out.add(t.slice(0, -1)); else if (!/s$/.test(t)) out.add(t + 's');
  return [...out];
}
// Every term of the glossary with its entry, longest first (for marking terms in running text): [[term, key]].
export function ruleTerms() {
  ruleFor('');
  return [...TERM_LIST];
}
let TERM_LIST = [];
// The glossary entry a term names (case does not matter), or null.
let TERMS = null;
export function ruleFor(term) {
  if (!TERMS) {
    TERMS = new Map();
    for (const k of Object.keys(RULES)) for (const a of ruleAliases(k)) if (!TERMS.has(a.toLowerCase())) { TERMS.set(a.toLowerCase(), k); TERM_LIST.push([a, k]); }
    TERM_LIST.sort((a, b) => b[0].length - a[0].length);
  }
  return TERMS.get(String(term).toLowerCase()) || null;
}
